const $=s=>document.querySelector(s),id=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join(''),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,key,salt,view='Übersicht',busy=false,session=null,queue=Promise.resolve(),timer;const STORE='stundenbuch.v1',days=['Montag','Dienstag','Mittwoch','Donnerstag','Freitag'],symbols=['—','−','0','+','++'];
const b64=a=>{let s='';for(let i=0;i<a.length;i+=8192)s+=String.fromCharCode(...a.subarray(i,i+8192));return btoa(s)},un64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
const bits = bytes => sjcl.codec.base64.toBits(b64(bytes));
const bytes = words => un64(sjcl.codec.base64.fromBits(words));
async function derive(p,s){
 if(crypto.subtle){let m=await crypto.subtle.importKey('raw',new TextEncoder().encode(p),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt:s,iterations:600000,hash:'SHA-256'},m,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
 return new Promise((resolve,reject)=>{const worker=new Worker('crypto-worker.js');worker.onmessage=e=>{worker.terminate();e.data.error?reject(Error(e.data.error)):resolve(e.data.key)};worker.onerror=()=>{worker.terminate();reject(Error('Passwortableitung fehlgeschlagen'))};worker.postMessage({password:p,salt:b64(s)})});
}
async function encrypt(k,iv,plain){return Array.isArray(k)?bytes(sjcl.mode.gcm.encrypt(new sjcl.cipher.aes(k),bits(plain),bits(iv),[],128)):new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},k,plain))}
async function decrypt(k,iv,cipher){return Array.isArray(k)?bytes(sjcl.mode.gcm.decrypt(new sjcl.cipher.aes(k),bits(cipher),bits(iv),[],128)):new Uint8Array(await crypto.subtle.decrypt({name:'AES-GCM',iv},k,cipher))}
function save(){const snapshot=JSON.stringify(data),k=key,s=salt;let job=queue.then(async()=>{let iv=crypto.getRandomValues(new Uint8Array(12)),cipher=await encrypt(k,iv,new TextEncoder().encode(snapshot));localStorage.setItem(STORE,JSON.stringify({v:1,salt:b64(s),iv:b64(iv),cipher:b64(new Uint8Array(cipher))}));});queue=job.catch(()=>{});return job}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function gate(){const exists=!!localStorage.getItem(STORE);$('#app').innerHTML=`<section class="lock panel">${location.protocol==='http:'&&!['localhost','127.0.0.1','[::1]'].includes(location.hostname)?'<p class="error">HTTP-Verbindung: Die gespeicherten Daten sind verschlüsselt, die App wird jedoch ungeschützt übertragen. Für sensible Daten HTTPS verwenden.</p>':''}<div class="brand"><span class="logo">▤</span> Klassenbuch<span style="color:#91a285">.</span></div><span class="eyebrow">Dein geschützter Arbeitsraum</span><h1>${exists?'Schön, dass du da bist.':'Mehr Zeit fürs Unterrichten.'}</h1><p>${exists?'Entsperre dein Klassenbuch mit deinem Passwort.':'Klassen organisieren. Mitarbeit festhalten. Entwicklung sehen. Alles an einem Ort.'}</p><form id="unlock"><label>Passwort ${exists?'':'festlegen'}</label><input id="password" type="password" autocomplete="${exists?'current-password':'new-password'}" minlength="12" required placeholder="Mindestens 12 Zeichen">${exists?'':'<label>Passwort wiederholen</label><input id="confirm" type="password" minlength="12" required autocomplete="new-password">'}<p id="error" class="error"></p><button class="primary">${exists?'Klassenbuch entsperren':'Geschütztes Klassenbuch anlegen'} →</button></form><small>♧ Lokal verschlüsselt mit AES-256-GCM. Das Passwort wird nicht gespeichert. Ohne Passwort können deine Daten nicht wiederhergestellt werden. Sichere regelmäßig ein verschlüsseltes Backup.</small><button id="restore">Verschlüsseltes Backup importieren</button></section>`;$('#unlock').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const p=$('#password').value;try{if(!exists&&p!==$('#confirm').value)throw Error('Die Passwörter stimmen nicht überein.');if(exists){let v=JSON.parse(localStorage.getItem(STORE));salt=un64(v.salt);key=await derive(p,salt);data=JSON.parse(new TextDecoder().decode(await decrypt(key,un64(v.iv),un64(v.cipher))))}else{salt=crypto.getRandomValues(new Uint8Array(16));key=await derive(p,salt);data={year:'2026/27',courses:[],slots:[],lessons:[]};await save()}$('#password').value='';resetTimer();render()}catch(err){key=null;data=null;$('#error').textContent=exists?'Entsperren fehlgeschlagen. Prüfe Passwort und Backup.':err.message}finally{busy=false}};$('#restore').onclick=importBackup}
function resetTimer(){clearTimeout(timer);if(key)timer=setTimeout(lock,300000)}async function lock(){await queue;key=null;data=null;session=null;clearTimeout(timer);gate()};['pointerdown','keydown'].forEach(e=>document.addEventListener(e,resetTimer));
function avg(s,c){let a=data.lessons.filter(l=>l.course===c).flatMap(l=>l.ratings.filter(r=>r.student===s)).map(r=>r.value);return a.length?(a.reduce((x,y)=>x+y,0)/a.length).toFixed(2).replace('.',','):'–'}
function render(){const all=data.courses.reduce((n,c)=>n+c.students.length,0);$('#app').innerHTML=`<aside><div class="brand"><span class="logo">▤</span> Klassenbuch<span style="color:#91a285">.</span></div><nav>${['Übersicht','Klassen & Kurse','Stundenplan','Jahresbilanz','Datenschutz'].map((n,i)=>`<button data-nav="${n}" class="${view===n?'active':''}"><span>${['◫','▦','▤','↗','♧'][i]}</span>${n}</button>`).join('')}</nav><footer><span class="badge">● Lokal verschlüsselt</span><p>Dein Unterricht. Deine Daten.</p><button id="lock" class="textbtn">↪ Klassenbuch sperren</button></footer></aside><main><header class="top"><span>Mein Arbeitsraum <span class="muted"> / ${esc(view)}</span></span><div class="row"><span class="badge">Schuljahr ${esc(data.year)}</span><button class="textbtn" id="lockTop">♧ Sperren</button></div></header><div id="content"></div></main>`;document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{view=b.dataset.nav;session=null;render()});$('#lock').onclick=$('#lockTop').onclick=lock;let c=$('#content');if(session){rating();return}if(view==='Übersicht'){c.innerHTML=`<div class="row"><div><span class="eyebrow">Mit Überblick in den Schultag</span><h1>Hallo, schönen Unterricht.</h1><p>Ein kleiner Moment nach der Stunde. Ein klares Bild fürs ganze Jahr.</p></div><button class="primary" id="start">＋ Stunde bewerten</button></div><div class="grid"><div class="panel stat"><div><small>MEINE KURSE</small><strong>${data.courses.length}</strong></div><small>Gemeinsam lernen</small></div><div class="panel stat"><div><small>SCHÜLERINNEN & SCHÜLER</small><strong>${all}</strong></div><small>Kurseinträge insgesamt</small></div><div class="panel stat"><div><small>ERFASSTE STUNDEN</small><strong>${data.lessons.length}</strong></div><small>In diesem Schuljahr</small></div></div><div class="split"><section class="panel"><div class="row"><h2>Deine Klassen & Kurse</h2><button class="textbtn" id="add">＋ Neuer Kurs</button></div>${coursesHTML()}</section><section><div class="hero"><span class="eyebrow">Wenige Klicks. Viel Überblick.</span><h2>Die Stunde ist vorbei.<br>Dein Eindruck bleibt.</h2><p>Gehe Karte für Karte durch deinen Kurs und halte die Mitarbeit direkt fest.</p><button class="primary" id="quick">Bewertung starten →</button></div><div class="panel" style="margin-top:20px"><h3>Ein sicherer Platz für deine Notizen</h3><p>Deine Einträge bleiben verschlüsselt in diesem Browser. Nach 5 Minuten Inaktivität wird die App gesperrt.</p></div></section></div>`;$('#add').onclick=courseForm;$('#start').onclick=$('#quick').onclick=startForm;bindCourses()}
if(view==='Klassen & Kurse'){c.innerHTML=`<div class="row"><div><span class="eyebrow">Organisation</span><h1>Klassen & Kurse</h1><p>Alle Lerngruppen. Jeder Schüler im Blick.</p></div><button class="primary" id="add">＋ Kurs anlegen</button></div><section class="panel">${coursesHTML(true)}</section>`;$('#add').onclick=courseForm;bindCourses()}
if(view==='Stundenplan'){c.innerHTML=`<div class="row"><div><span class="eyebrow">Deine Woche</span><h1>Stundenplan</h1><p>Ein fester Platz für jeden Kurs.</p></div><button class="primary" id="addslot">＋ Stunde hinzufügen</button></div><div class="week">${days.map((d,i)=>`<section class="day"><h3>${d}</h3>${data.slots.filter(s=>s.day===i).sort((a,b)=>a.time.localeCompare(b.time)).map(s=>`<div class="panel"><strong>${esc(s.time)}</strong><p>${esc(data.courses.find(c=>c.id===s.course)?.name||'Entfernter Kurs')}</p><small>${esc(s.room)}</small><button class="textbtn" data-del-slot="${s.id}" aria-label="Stunde entfernen">×</button></div>`).join('')||'<p>Keine Stunden</p>'}</section>`).join('')}</div>`;$('#addslot').onclick=slotForm;document.querySelectorAll('[data-del-slot]').forEach(b=>b.onclick=()=>mutate(()=>data.slots=data.slots.filter(s=>s.id!==b.dataset.delSlot)))}
if(view==='Jahresbilanz')balance();if(view==='Datenschutz'){c.innerHTML=`<span class="eyebrow">Dein geschützter Arbeitsraum</span><h1>Daten & Sicherheit</h1><div class="panel"><h2>Nur mit deinem Passwort lesbar</h2><p>Klassen, Namen, Stundenplan und Bewertungen werden gemeinsam mit AES-256-GCM verschlüsselt. Der Schlüssel wird mit PBKDF2-SHA-256 (600.000 Iterationen) aus deinem Passwort abgeleitet und nur während der Sitzung im Arbeitsspeicher gehalten.</p><p>Es gibt keine Cloud-Synchronisierung. Browserdaten löschen bedeutet Datenverlust, wenn kein Backup vorliegt. Nutze die App auf einem vertrauenswürdigen Gerät. Ein entsperrter Browser kann die Daten anzeigen.</p><button class="primary" id="export">↓ Verschlüsseltes Backup</button> <button id="import">Backup wiederherstellen</button><h3>Schuljahr</h3><p>Die Bezeichnung gilt für den gesamten aktuellen Datenbestand. Eine Änderung filtert oder archiviert keine Bewertungen. Für ein neues Schuljahr zuerst ein Backup sichern und einen getrennten Browserbereich verwenden.</p><form id="yearform"><label>Bezeichnung des Schuljahres</label><input id="year" value="${esc(data.year)}" required><button style="margin-top:12px">Bezeichnung speichern</button></form></div>`;$('#export').onclick=exportBackup;$('#import').onclick=importBackup;$('#yearform').onsubmit=e=>{e.preventDefault();mutate(()=>data.year=$('#year').value)}}}
function coursesHTML(edit=false){return data.courses.length?data.courses.map(c=>`<div class="course"><div class="row"><div class="icon">${esc(c.name.slice(0,2))}</div><div><h3>${esc(c.name)}</h3><small>${esc(c.subject)} · ${c.students.length} Schüler · ${data.lessons.filter(l=>l.course===c.id).length} Stunden</small></div></div><div><button data-rate="${c.id}" class="textbtn">Bewerten →</button>${edit?`<button data-edit="${c.id}" class="textbtn">Bearbeiten</button>`:''}</div></div>`).join(''):'<div class="empty">▦<h3>Hier beginnt dein Schuljahr.</h3><p>Lege deinen ersten Kurs mit seinen Schülerinnen und Schülern an.</p></div>'}
function bindCourses(){document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>startForm(b.dataset.rate));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>courseForm(b.dataset.edit))}
function modal(html,submit){$('#modal').innerHTML=html;$('#modal').showModal();$('#modal').querySelector('[data-close]').onclick=()=>$('#modal').close();$('#modal').querySelector('form').onsubmit=async e=>{e.preventDefault();try{await submit(new FormData(e.target));$('#modal').close()}catch(err){toast(err.message)}}}
async function mutate(fn){const previous=structuredClone(data),previousSession=session;try{fn();await save();render()}catch(error){data=previous;session=previousSession;toast('Speichern fehlgeschlagen. Bitte Backup exportieren.');throw error}}
function courseForm(cid){let c=data.courses.find(c=>c.id===cid);modal(`<h2>${c?'Kurs bearbeiten':'Neuer Kurs'}</h2><form><label>Klasse / Kurs</label><input name="name" required value="${esc(c?.name||'')}" placeholder="z. B. 8a"><label>Fach</label><input name="subject" required value="${esc(c?.subject||'')}" placeholder="z. B. Deutsch"><label>Schülerinnen & Schüler – ein Name pro Zeile</label><textarea name="students" rows="7" required placeholder="Vorname Nachname">${esc(c?.students.map(s=>s.name).join('\n')||'')}</textarea><small>Unveränderte Namen behalten ihren Verlauf. Entfernte Namen bleiben in vergangenen Stunden gespeichert.</small><div class="actions"><button type="button" data-close>Abbrechen</button><button class="primary">Speichern</button></div></form>`,async f=>{let names=f.get('students').split('\n').map(n=>n.trim()).filter(Boolean);if(new Set(names).size!==names.length)throw Error('Bitte eindeutige Namen verwenden.');await mutate(()=>{const students=names.map(name=>c?.students.find(s=>s.name===name)||{id:id(),name});if(c)Object.assign(c,{name:f.get('name'),subject:f.get('subject'),students});else data.courses.push({id:id(),name:f.get('name'),subject:f.get('subject'),students})})})}
function options(cid){return data.courses.map(c=>`<option value="${c.id}" ${cid===c.id?'selected':''}>${esc(c.name)} · ${esc(c.subject)}</option>`).join('')}
function startForm(cid){if(!data.courses.length){courseForm();return}modal(`<h2>Stunde bewerten</h2><form><label>Kurs</label><select name="course">${options(typeof cid==='string'?cid:null)}</select><label>Datum</label><input name="date" type="date" value="${new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10)}" required><label>Stunde / Thema</label><input name="title" required placeholder="z. B. 3. Stunde · Gedichtanalyse"><div class="actions"><button type="button" data-close>Abbrechen</button><button class="primary">Karten starten →</button></div></form>`,f=>{session={id:id(),course:f.get('course'),date:f.get('date'),title:f.get('title'),ratings:[],index:0};render()})}
function rating(){let c=data.courses.find(c=>c.id===session.course),s=c.students[session.index];$('#content').innerHTML=`<div class="row"><div><span class="eyebrow">Mitarbeit festhalten</span><h1>${esc(c.name)} <span class="muted">· ${esc(c.subject)}</span></h1><p>${esc(session.date)} · ${esc(session.title)}</p></div><button id="cancel">Abbrechen</button></div><section class="cards"><div class="row"><span>${session.index} von ${c.students.length} bearbeitet</span><small>Eine Karte. Ein Eindruck.</small></div><div class="progress"><i style="width:${session.index/c.students.length*100}%"></i></div>${s?`<div class="student"><div class="avatar">${esc(s.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</div><h1>${esc(s.name)}</h1><p>Wie war die Mitarbeit in dieser Stunde?</p></div><div class="ratings">${[2,1,0,-1,-2].map(v=>`<button data-value="${v}">${symbols[v+2]}</button>`).join('')}</div><p><button class="textbtn" id="skip">Abwesend / überspringen →</button></p>`:`<div class="student"><div class="avatar">✓</div><h1>Alles im Blick.</h1><p>${session.ratings.length} Bewertungen sind bereit.</p><button class="primary" id="finish">Stunde verschlüsselt speichern</button></div>`}<button class="textbtn" id="back" ${session.index?'':'disabled'}>← Vorherige Karte</button><p><small>++ = 2 · + = 1 · 0 = 0 · − = −1 · — = −2<br>Übersprungene Schüler fließen nicht in den Schnitt ein.</small></p></section>`;$('#cancel').onclick=()=>{if(confirm('Diese ungespeicherte Stunde verwerfen?')){session=null;render()}};$('#back').onclick=()=>{session.index--;session.ratings=session.ratings.filter(r=>r.student!==c.students[session.index].id);rating()};document.querySelectorAll('[data-value]').forEach(b=>b.onclick=()=>{session.ratings.push({student:s.id,name:s.name,value:Number(b.dataset.value)});session.index++;rating()});if(s)$('#skip').onclick=()=>{session.index++;rating()};else $('#finish').onclick=async()=>{const button=$('#finish');button.disabled=true;try{const l={...session};delete l.index;await mutate(()=>{data.lessons.push(l);session=null});toast('Stunde gespeichert')}catch{button.disabled=false}};}
function slotForm(){if(!data.courses.length){courseForm();return}modal(`<h2>Stunde hinzufügen</h2><form><label>Kurs</label><select name="course">${options()}</select><label>Wochentag</label><select name="day">${days.map((d,i)=>`<option value="${i}">${d}</option>`).join('')}</select><label>Beginn</label><input name="time" type="time" required value="08:00"><label>Raum</label><input name="room" placeholder="z. B. B 204"><div class="actions"><button type="button" data-close>Abbrechen</button><button class="primary">Hinzufügen</button></div></form>`,f=>mutate(()=>data.slots.push({id:id(),course:f.get('course'),day:Number(f.get('day')),time:f.get('time'),room:f.get('room')})))}
function balance(){const c=$('#content');c.innerHTML=`<span class="eyebrow">Entwicklung sichtbar machen</span><h1>Jahresbilanz</h1><p>Alle Einträge im Schuljahr ${esc(data.year)}. Arithmetischer Punkteschnitt von −2 bis +2, keine Schulnote.</p><select id="coursefilter" style="max-width:350px;margin:10px 0 25px">${options()}</select><div id="results"></div>`;function results(){let course=data.courses.find(c=>c.id===$('#coursefilter').value);if(!course){$('#results').innerHTML='<div class="panel empty">Lege zuerst einen Kurs an.</div>';return}let lessons=data.lessons.filter(l=>l.course===course.id),students=new Map(course.students.map(s=>[s.id,s.name]));lessons.forEach(l=>l.ratings.forEach(r=>students.set(r.student,r.name)));$('#results').innerHTML=`<section class="panel"><div class="row"><h2>${esc(course.name)} · ${lessons.length} erfasste Stunden</h2></div><table><thead><tr><th>Name</th><th>Bewertungen</th><th>++ / + / 0 / − / —</th><th>Schnitt</th></tr></thead><tbody>${[...students].map(([sid,name])=>{let r=lessons.flatMap(l=>l.ratings.filter(r=>r.student===sid));return `<tr><td>${esc(name)}</td><td>${r.length}</td><td>${[2,1,0,-1,-2].map(v=>r.filter(a=>a.value===v).length).join(' / ')}</td><td><strong>${avg(sid,course.id)}</strong></td></tr>`}).join('')}</tbody></table></section><section class="panel" style="margin-top:25px"><h2>Stundenverlauf</h2>${lessons.slice().reverse().map(l=>`<details style="padding:15px 0;border-bottom:1px solid #edf0e9"><summary>${esc(l.date)} · ${esc(l.title)} <small>(${l.ratings.length} Bewertungen)</small></summary><table>${l.ratings.map(r=>`<tr><td>${esc(r.name)}</td><td>${symbols[r.value+2]}</td></tr>`).join('')}</table><button class="textbtn" data-delete="${l.id}">Stunde löschen</button></details>`).join('')||'<p>Noch keine Stunden erfasst.</p>'}</section>`;document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('Diese Stunde und ihre Bewertungen dauerhaft löschen?'))mutate(()=>data.lessons=data.lessons.filter(l=>l.id!==b.dataset.delete))})}$('#coursefilter').onchange=results;results()}
async function exportBackup(){await queue;let raw=localStorage.getItem(STORE);if(!raw)return;let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([raw],{type:'application/json'}));a.download='klassenbuch-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function importBackup(){let input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{const raw=await input.files[0].text(),v=JSON.parse(raw);if(v.v!==1||!v.salt||!v.iv||!v.cipher)throw Error('Ungültiges Backup');const password=prompt('Passwort des Backups eingeben:');if(!password)return;let k=await derive(password,un64(v.salt)),d=JSON.parse(new TextDecoder().decode(await decrypt(k,un64(v.iv),un64(v.cipher))));if(!Array.isArray(d.courses)||!Array.isArray(d.lessons)||!Array.isArray(d.slots))throw Error('Ungültige Daten');if(localStorage.getItem(STORE)&&!confirm('Aktuelle Daten durch das Backup ersetzen? Exportiere vorher bei Bedarf eine Sicherung.'))return;await queue;localStorage.setItem(STORE,raw);await lock();toast('Backup importiert. Bitte entsperren.')}catch{toast('Import fehlgeschlagen: Passwort oder Datei prüfen.')}};input.click()}
gate();
